//! Every answer in this file was produced by **doc-gen4**, not by the Rust code
//! it checks.
//!
//! `tests/data/docgen4-expected.json` is generated by
//! `tests/oracle/gen-docgen4-expected.ts`, which runs `docStringToHtml` under
//! `lake env lean` in the measurement target and prints the bytes. The corpus is
//! every docstring in that package's IR plus hand-written cases for the corners
//! it does not contain. Regenerate with:
//!
//! ```text
//! deno run --allow-read --allow-write --allow-run --allow-env \
//!   crates/litedoc4-md/tests/oracle/gen-docgen4-expected.ts
//! ... --check      # verify the committed file
//! ... --full PATH  # write every case, for a check by hand (no test reads it)
//! ```
//!
//! # Why the whole corpus *can* be compared, auto-links included
//!
//! doc-gen4 resolves names against the environment, so a naive run of it would
//! produce anchors this milestone step cannot produce, and the comparison would
//! have to exclude every docstring mentioning a documented name — which is most
//! of them. It does not have to: `nameToLink?` reads *only* the `AnalyzerResult`
//! in its context, and the dumper hands it the empty one. Every lookup then
//! misses, which is precisely [`NoLinks`]. So nothing is excluded and nothing is
//! normalised away — **when the port was made (M1-c), 4,987 of 4,989 cases were
//! compared byte for byte**, the two exceptions being the inputs that kill the
//! Lean side outright ([`the_inputs_that_kill_doc_gen4_here`]).
//!
//! # What runs now, and what the oracle is for【判断 2026-08-16】
//!
//! **The committed sample, and only that** — the whole-corpus test was deleted.
//! It read a multi-megabyte `--full` recording from `/private/tmp`, which is
//! emptied, so it spent its life either red or regenerated at the cost of a
//! doc-gen4 run over every docstring in the package.
//!
//! **The point of this oracle is not "doc-gen4 is right".** It is not: it dies
//! outright on a NUL in a fenced code block and on a header-only GFM table, and
//! the generator has to resume around 99 such inputs. What it *defines* is the
//! **dialect** — which extensions are on, how entities and math are read, where
//! relative links resolve from — and Lean's docstrings are written against that
//! dialect. Byte equality is a cheap sufficient condition for "the dialect did
//! not move"; writing a judge for dialect equality directly would be a second
//! implementation sharing this one's mistakes.
//!
//! That claim is about the *rules*, and the committed sample is a designed cover
//! of them (every hand-written case, then a greedy cover of the output features,
//! then the first case showing each byte-level feature, then a stride over the
//! rest). **The 4,414 cases outside the sample are not checked** — that is the
//! price, stated rather than hidden.
//!
//! What this does *not* check is `nameToLink?` itself. That is the next
//! milestone step's, and it will need an oracle run with a real environment.

use litedoc4_md::{NoLinks, Renderer};
use serde::Deserialize;

const FIXTURE: &str = include_str!("data/docgen4-expected.json");

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Expected {
    /// How the answers were produced, for the report a failure prints.
    oracle: String,
    lean_toolchain: String,
    doc_gen4_rev: Option<String>,
    /// How many distinct docstrings the target package's IR holds.
    ir_docstrings: usize,
    /// The `getRoot` values the corpus was rendered at.
    roots: Vec<String>,
    cases: Vec<Case>,
    /// The inputs that kill the Lean side, recorded rather than expected.
    crashes_doc_gen4: Vec<Crasher>,
}

#[derive(Deserialize)]
struct Case {
    /// Where the docstring came from: a declaration name, or `curated: …`.
    what: String,
    /// The `getRoot` this case was rendered at.
    root: String,
    md: String,
    /// doc-gen4's bytes.
    html: String,
}

#[derive(Deserialize)]
struct Crasher {
    what: String,
    md: String,
}

fn expected() -> Expected {
    serde_json::from_str(FIXTURE).expect("tests/data/docgen4-expected.json is valid")
}

/// Renders an input so a failure names the code points rather than printing
/// control characters into the terminal.
fn show(s: &str) -> String {
    let head: String = s
        .chars()
        .take(200)
        .map(|c| {
            if c.is_ascii_graphic() || c == ' ' {
                c.to_string()
            } else {
                format!("<U+{:04X}>", c as u32)
            }
        })
        .collect();
    if s.chars().count() > 200 {
        format!("{head}...")
    } else {
        head
    }
}

/// The first byte at which two strings differ, with a window around it — a
/// whole-page diff of a 4 KB docstring is unreadable.
fn first_difference(want: &str, got: &str) -> String {
    let at = want
        .as_bytes()
        .iter()
        .zip(got.as_bytes())
        .position(|(a, b)| a != b)
        .unwrap_or_else(|| want.len().min(got.len()));
    let from = at.saturating_sub(40);
    let window = |s: &str| {
        let to = (at + 40).min(s.len());
        let from = from.min(s.len());
        show(&String::from_utf8_lossy(&s.as_bytes()[from..to]))
    };
    format!(
        "byte {at} of {} (doc-gen4) / {} (here)\n  doc-gen4: …{}…\n  here:     …{}…",
        want.len(),
        got.len(),
        window(want),
        window(got)
    )
}

/// Compares one case, returning a description of the disagreement.
fn check(case: &Case) -> Option<String> {
    let got = Renderer::new(&case.root, &NoLinks).docstring(&case.md);
    if got == case.html {
        return None;
    }
    Some(format!(
        "{} (root {:?})\n  input: {}\n  {}",
        case.what,
        case.root,
        show(&case.md),
        first_difference(&case.html, &got)
    ))
}

#[test]
fn the_fixture_is_doc_gen4s_own_output() {
    let e = expected();
    assert!(e.oracle.contains("docStringToHtml"), "{}", e.oracle);
    assert_eq!(e.lean_toolchain, "leanprover/lean4:v4.31.0");
    assert_eq!(
        e.doc_gen4_rev.as_deref(),
        Some("0bc516c1b9db83658d6475c40d9b1ed71219b921"),
        "the doc-gen4 the reference tree was built with"
    );
    // 実測: the target package's IR holds this many distinct docstrings.
    assert_eq!(e.ir_docstrings, 4_858);
    // The root reaches the bytes, so more than one of them has to be exercised.
    assert_eq!(e.roots, ["./", ".././", "../.././"]);
    assert!(e.cases.len() >= 300, "only {} cases", e.cases.len());
    assert_eq!(e.crashes_doc_gen4.len(), 2);
}

/// Every case comes out the way the fixture says it does.
///
/// **The fixture was doc-gen4's output until 2026-08-22 and is this renderer's
/// now** (`docs/plans/feature-sweep.md` §3【決定 1】/ C-4). Feature-sweep C-1
/// converts `$…$` to MathML at build time, which doc-gen4 does not do, so five
/// of these 327 cases could never agree with it again — and a comparison that
/// is right about 322 cases and wrong about 5 by design is a comparison nobody
/// reads after the first time. The role changed **once**, deliberately, with the
/// regenerator below put in the tree so that the next change does not need a
/// decision at all.
///
/// What is lost is stated rather than hidden: this no longer says "the dialect
/// did not move". `tests/oracle/gen-docgen4-expected.ts` still runs and still
/// produces doc-gen4's answers, so that claim can be re-checked deliberately;
/// it is simply not what `cargo test` asserts.
#[test]
fn every_case_matches_the_frozen_output() {
    let e = expected();
    if bless_requested() {
        bless(&e);
        return;
    }
    let failures: Vec<String> = e.cases.iter().filter_map(check).collect();
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from the frozen output:\n{}\n\n\
         If the change is intended, regenerate with:\n    \
         LITEDOC4_BLESS=1 cargo test -p litedoc4-md --test docgen4",
        failures.len(),
        e.cases.len(),
        failures
            .iter()
            .take(10)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

/// `LITEDOC4_BLESS=1` — rewrite the fixture instead of comparing against it.
fn bless_requested() -> bool {
    std::env::var("LITEDOC4_BLESS").is_ok_and(|value| value == "1")
}

/// Rewrites `tests/data/docgen4-expected.json` from this renderer's output, and
/// **prints every case it changed**.
///
/// The printing is the point. A regenerator that silently rewrites a file turns
/// "review the diff" into a diff of one 220 KB line, which is not a review. The
/// procedure `docs/plans/feature-sweep.md` §3 asks for — *what changed and
/// because of which item* — is read out of this output.
///
/// It is **idempotent, and asserts that it is**: a second run must change
/// nothing and leave the bytes alone. That is what makes "the file this writes
/// is the file the test reads" a checked statement rather than a hope, and it
/// catches the failure where re-serialising moves key order or escaping and
/// every future diff is the whole file.
fn bless(e: &Expected) {
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/docgen4-expected.json");
    let original = std::fs::read_to_string(&path).expect("the fixture is readable");
    let mut document: serde_json::Value =
        serde_json::from_str(&original).expect("the fixture is JSON");

    // The round trip **before** any edit: if this is not the byte the file
    // holds, every value below would arrive with a different spelling and the
    // change this run is about would be invisible among them.
    let round_trip = serde_json::to_string(&document).expect("it came from JSON") + "\n";
    assert_eq!(
        round_trip, original,
        "re-serialising the fixture does not reproduce it; blessing would rewrite \
         the whole file and no diff of it could be reviewed"
    );

    let cases = document
        .get_mut("cases")
        .and_then(serde_json::Value::as_array_mut)
        .expect("the fixture has cases");
    let mut changed = 0usize;
    for (case, value) in e.cases.iter().zip(cases.iter_mut()) {
        let got = Renderer::new(&case.root, &NoLinks).docstring(&case.md);
        if got == case.html {
            continue;
        }
        changed += 1;
        println!(
            "bless {}\n  was: {}\n  now: {}",
            case.what,
            show(&case.html),
            show(&got)
        );
        value["html"] = serde_json::Value::String(got);
    }
    let updated = serde_json::to_string(&document).expect("values are strings") + "\n";
    std::fs::write(&path, &updated).expect("the fixture is writable");
    println!(
        "bless: {changed} of {} case(s) rewritten in {}",
        e.cases.len(),
        path.display()
    );
    assert_eq!(
        serde_json::to_string(
            &serde_json::from_str::<serde_json::Value>(&updated).expect("what was written is JSON")
        )
        .expect("round trip")
            + "\n",
        updated,
        "the file this wrote does not round-trip"
    );
}

/// The committed sample has to keep reaching every branch of the renderer, or
/// a machine without the target package is checking less than it looks.
///
/// The markers are on the *output* side on purpose: they are what a wrong
/// branch would change. `heading id` and `find/?pattern=` are the two pieces of
/// this milestone step that are not md4c's and not a plain tag.
#[test]
fn the_sample_still_covers_the_output() {
    let e = expected();
    let all: String = e.cases.iter().map(|c| c.html.as_str()).collect();
    for marker in [
        "<p>",
        "<ul>",
        "<ol>",
        "<ol start=\"",
        "<li>",
        "<hr>\n",
        "<h1 ",
        "<h6 ",
        "class=\"markdown-heading\"",
        "class=\"hover-link\"",
        "<pre><code>",
        "<pre><code class=\"language-",
        "<blockquote>",
        "<table><thead><tr><th>",
        "<tbody><tr><td>",
        "<em>",
        "<strong>",
        "<del>",
        "<br>\n",
        "<code>",
        "<img src=\"",
        " title=\"",
        "<a href=\"",
        "find/?pattern=",
        "$",
        "$$",
        "<input type=\"checkbox\" checked=\"\" disabled=\"\">",
        "<input type=\"checkbox\" disabled=\"\">",
        "&amp;",
        "&lt;",
        "&quot;",
        "\u{FFFD}",
    ] {
        assert!(
            all.contains(marker),
            "nothing in the sample produces {marker:?}"
        );
    }
    // The three doc-gen4 cannot emit under `MD_FLAG_NOHTML` and the two flags
    // it leaves off. Their appearance would mean the dialect had drifted.
    for never in ["<u>", "<x-wikilink"] {
        assert!(
            !all.contains(never),
            "{never:?} appeared; the dialect drifted"
        );
    }
}

/// The inputs that kill doc-gen4, and what this crate does instead.
///
/// Both are undefined behaviour on the Lean side (see `tests/md4lean.rs`), so
/// there are no bytes to match; what is pinned is that neither crashes us and
/// that both still render something.
#[test]
fn the_inputs_that_kill_doc_gen4_here() {
    for crasher in expected().crashes_doc_gen4 {
        let got = Renderer::new("./", &NoLinks).docstring(&crasher.md);
        assert!(!got.is_empty(), "{}", crasher.what);
    }
    // A NUL inside a fenced code block: U+FFFD, then the byte md4c re-reports.
    assert_eq!(
        Renderer::new("./", &NoLinks).docstring("```\na\0b\n```\n"),
        "<pre><code>a\u{FFFD}\0b\n</code></pre>"
    );
    // A table with a header and no body rows: an empty `<tbody>`.
    assert_eq!(
        Renderer::new("./", &NoLinks).docstring("| a | b |\n|---|---|\n"),
        "<table><thead><tr><th>a</th><th>b</th></tr></thead><tbody></tbody></table>"
    );
}
